css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 40px; align-items: start;}
.mz .unir-col{display: flex; flex-direction: column; gap: 7px;}
.mz .unir-item{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 10px; text-align: center; font-size: 13px; font-weight: 700;}
.mz .serie-bloque{display: flex; flex-direction: column; gap: 6px;}
.mz .serie-fila{display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px;}
.mz .serie-caja{border: 1.5px solid var(--bosque); border-radius: 6px; min-height: 34px; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; text-align: center; padding: 3px;}
.mz .serie-caja.lleno{background: #f4f4f4;}
.mz .evento-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 40px; align-items: start;}
.mz .evento-col{display: flex; flex-direction: column; gap: 7px;}
.mz .evento-item{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 10px; text-align: center; font-size: 13px; font-weight: 700;}
.mz .prob-lista{display: flex; flex-direction: column; gap: 7px;}
.mz .prob{font-size: 13px; line-height: 1.5;}
.mz .hueco-cuadrado{display: inline-block; width: 38px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px; vertical-align: middle; margin: 0 4px;}
.mz .hueco-linea{display: inline-block; min-width: 100px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .prob{line-height: 1.875 !important;}
